# Item 7: gene rankings from DESeq2 (Wald) and limma-voom (moderated t) on exactly the splits
# generated by Python (seed 42).  usage: Rscript rankings.R <inputs_dir> <splits.tsv> <out_dir>
#   full data           : DESeq2 + limma-voom      -> rank_<method>_full.tsv
#   outer training folds: DESeq2 + limma-voom      -> rank_<method>_outer<f>.tsv
#   inner training split: limma-voom only (for S2) -> rank_limma_outer<f>_inner<j>.tsv
args <- commandArgs(trailingOnly = TRUE)
source(file.path(dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value = TRUE)))), "common.R"))
inp <- args[1]; spl <- args[2]; out <- args[3]
d <- load_inputs(inp); counts <- d$counts; smp <- d$samples
sp <- read.delim(spl, stringsAsFactors = FALSE)
keys <- split(sp$idx, sp$key)            # 1-based sample indices

do_one <- function(name, idx, methods) {
  t0 <- Sys.time()
  s <- smp[idx, ]; cn <- counts[, idx, drop = FALSE]
  if ("deseq2" %in% methods) write_tsv(deseq_condition(cn, s), file.path(out, sprintf("rank_deseq2_%s.tsv", name)))
  if ("limma" %in% methods)  write_tsv(limma_condition(cn, s),  file.path(out, sprintf("rank_limma_%s.tsv", name)))
  cat(sprintf("%-16s n=%d  %.0fs\n", name, length(idx), as.numeric(difftime(Sys.time(), t0, units = "secs"))))
}

do_one("full", seq_len(ncol(counts)), c("deseq2", "limma"))
for (k in grep("_train$", names(keys), value = TRUE)) {
  name <- sub("_train$", "", k)
  methods <- if (grepl("_inner", name)) "limma" else c("deseq2", "limma")
  do_one(name, keys[[k]], methods)
}
cat("done\n")
